      chargement: [d.dateChargement, d.dateFin].filter(Boolean).join(' → '), statut: d.statut,
      notes: analyse ? { resume: analyse.resume, dates: analyse.precisionDates, flexibilite: analyse.flexibiliteDates, contraintes: analyse.contraintes } : null,
    };
