// L'IA au service de la carte des demandes, à deux endroits seulement :
// 1. à l'import, elle lit les notes d'un dossier (corps de la fiche Notion, description et
//    commentaires noCRM) et en tire une fiche courte et structurée — une fois par version des
//    notes, grâce à l'empreinte ;
// 2. à la demande, elle donne son avis sur un groupage proposé par l'algorithme.
// Elle ne décide rien : les combinaisons et leurs notes viennent de moteur/suggestions.js.
// Les notes et les mails sont des DONNÉES : aucune instruction qu'ils contiendraient n'est suivie.

const LONGUEUR_NOTES_MAX = 6000;
const FLEXIBILITES = ['souple', 'stricte', 'inconnue'];

// Repères normalisés : mesurables (l'évaluation compare des listes), filtrables dans la page.
// Le détail en clair reste dans `contraintes`.
const REPERES = {
  piano: 'piano',
  objet_lourd: 'objet lourd (coffre-fort, frigo américain…)',
  fragile: 'objets fragiles ou de valeur',
  etage_sans_ascenseur: 'étage sans ascenseur',
  acces_difficile: 'accès difficile (rue étroite, stationnement, portage long)',
  monte_meuble: 'monte-meuble',
  stockage: 'stockage / garde-meuble',
  demontage: 'démontage / remontage',
  horaire_impose: 'horaire imposé',
  client_indecis: 'client indécis (compare des devis, pas encore décidé)',
};

// Les notes d'un dossier, en un seul texte borné, sources étiquetées.
function texteNotes({ corpsNotion = '', descriptionNocrm = '', commentairesNocrm = [] } = {}) {
  const morceaux = [];
  if (String(corpsNotion).trim()) morceaux.push(`[Fiche Notion]\n${String(corpsNotion).trim()}`);
  if (String(descriptionNocrm).trim()) morceaux.push(`[Description noCRM]\n${String(descriptionNocrm).trim()}`);
  const commentaires = (commentairesNocrm || [])
    .map((c) => `${String(c.created_at || '').slice(0, 10)} — ${String(c.content || c.text || '').trim()}`)
    .filter((c) => !/—\s*$/.test(c));
  if (commentaires.length) morceaux.push(`[Commentaires noCRM]\n${commentaires.join('\n')}`);
  const texte = morceaux.join('\n\n');
  return texte.length > LONGUEUR_NOTES_MAX ? `${texte.slice(0, LONGUEUR_NOTES_MAX)}\n[…]` : texte;
}

// Empreinte FNV-1a : des notes inchangées ne repartent pas chez OpenAI.
function empreinte(texte) {
  let h = 0x811c9dc5;
  for (const c of String(texte)) {
    h ^= c.codePointAt(0);
    h = Math.imul(h, 0x01000193) >>> 0;
  }
  return h.toString(16).padStart(8, '0');
}

function requeteAnalyseNotes(dossier, texte, modele) {
  return {
