const lus = $input.all().map((i) => i.json).filter((l) => l && l.id);

// Leçon noCRM : un filtre accepté puis ignoré rend 200 avec TOUTE la base.
const horsColonnes = lus.filter((l) => !etapes.includes(Number(l.step_id)));
if (horsColonnes.length) {
  throw new Error('Le filtre ?step= de noCRM n’a pas filtré (' + horsColonnes.length + ' dossiers hors colonnes) — import interrompu.');
}
// Une colonne qui remplit toutes ses pages a peut-être d’autres dossiers derrière : on ne devine pas.
for (const e of etapes) {
  const n = lus.filter((l) => Number(l.step_id) === e).length;
  if (n >= r.pagesMax * 100) throw new Error(`Colonne ${r.etapes[e]} : ${n} dossiers, pagesMax trop bas — import interrompu.`);
}

const maintenant = new Date().toISOString();
const vus = new Set();
const vivantes = [];
const ecartes = [];
for (const lead of lus) {
  if (vus.has(lead.id)) continue;
  vus.add(lead.id);
  const v = demandeActive(lead, maintenant, r);
  if (!v.active) { ecartes.push({ id: lead.id, raison: v.raison }); continue; }
  vivantes.push({ json: {
    lead: { id: lead.id, title: lead.title, amount: lead.amount, description: lead.description, status: lead.status,
      step_id: lead.step_id, updated_at: lead.updated_at, created_at: lead.created_at },
    motRecherche: (motsDuNom(lead.title).sort((a, b) => b.length - a.length)[0]) || null,
  } });
}
// Aucun dossier vivant : un item témoin, pour que la table soit quand même vidée des morts.
return vivantes.length ? vivantes : [{ json: { aucune: true, ecartes } }];

// Lecture d'un dossier de groupage : opportunité noCRM × fiche Notion.
// Portage de Sam'Déménage/outils/Groupage/collecte.py et lib/fiche_notion.py (parser_corps).
// Fonctions pures, sans dépendance : le même fichier sert au nœud Code de WF1 (inséré par
// construire.mjs, mots-clés `export` retirés) et aux tests Node.
// Règle maîtresse : le CORPS de la fiche fait foi, les propriétés ne comblent que ce qu'il ne porte pas.

const DEPTS_IDF = ['75', '77', '78', '91', '92', '93', '94', '95'];

function sansAccents(s) {
  return String(s || '').normalize('NFD').replace(/\p{Mn}/gu, '').toLowerCase();
}

function nombres(s) {
  return (String(s || '').match(/\d+(?:[.,]\d+)?/g) || []).map((x) => parseFloat(x.replace(',', '.')));
}

function premierNombre(s) {
  const n = nombres(s);
  return n.length ? n[0] : null;
}

function nbEtage(s) {
  if (s === null || s === undefined) return null;
  const brut = sansAccents(s).trim();
  if (!brut) return null;
  let m = brut.match(/^\s*r\s*\+\s*(\d+)/);
  if (m) return parseInt(m[1], 10);
  if (/^\s*(rdc|rez|plain[- ]?pied|0\b)/.test(brut)) return 0;
  m = brut.match(/\d+/);
  return m ? parseInt(m[0], 10) : null;
}

const VOLUME = /(\d+(?:[.,]\d+)?)\s*m\s*(?:3|³)/gi;

// Un volume composite n'est jamais réduit à son premier nombre :
// « 7 m3 + 40 m3 = 47 m3 total » vaut 47 ; plusieurs volumes sans total → null + alerte.
function lireVolume(texte) {
  const trouves = [...String(texte || '').matchAll(VOLUME)].map((m) => [m.index, parseFloat(m[1].replace(',', '.'))]);
  if (!trouves.length) return [null, null];
  if (trouves.length === 1) return [trouves[0][1], null];
  const nu = sansAccents(texte);
  const reperes = [...nu.matchAll(/total|=/g)].map((m) => m.index);
  const liste = trouves.map((t) => t[1]);
  if (reperes.length) {
    let meilleur = trouves[0];
    let dist = Infinity;
    for (const t of trouves) {
      const d = Math.min(...reperes.map((r) => Math.abs(t[0] - r)));
      if (d < dist) { dist = d; meilleur = t; }
    }
    return [meilleur[1], `Volume composite dans la fiche (${liste.join(' + ')} m³) — total retenu : ${meilleur[1]} m³.`];
  }
  return [null, `Volume composite non tranché (${liste.join(' / ')} m³) : aucun total indiqué dans la fiche.`];
}

function valeurApres(ligne) {
  const i = ligne.indexOf(':');
  return i >= 0 ? ligne.slice(i + 1).trim() : '';
}

const coche = (ligne) => ligne.trimStart().startsWith('- [x]');
const libelleCase = (ligne) => ligne.replace(/^\s*-\s*\[[ x]\]\s*/, '');

// --- Découpage en sections -------------------------------------------------------------

const SECTIONS = [
  ['entete', null],
  ['offre', /details? offre/],
  ['depart', /^depart\b/],
  ['arrivee', /^arrivee\b/],
  ['demontage', /meubles? a demonter/],
  ['cartons', /mise en cartons?/],
  ['materiel', /materiel a livrer/],
  ['lourds', /meubles? lourds?/],
  ['itineraire', /itineraires?/],
];

function decouper(lignes) {
  const sections = { fin: [] };
  for (const [nom] of SECTIONS) sections[nom] = [];
  let courante = 'entete';
  for (const ligne of lignes) {
    if (ligne.startsWith('###')) {
      const titre = sansAccents(ligne.replace(/^[#\s]+/, '').trim());
      const trouve = SECTIONS.find(([, motif]) => motif && motif.test(titre));
      if (trouve) {
        courante = trouve[0];
        sections[courante].push(ligne);
        continue;
      }
      courante = 'fin';
    }
    sections[courante].push(ligne);
  }
  if (sections.itineraire.length) {
    const garde = [];
    const queue = [];
    for (const ligne of sections.itineraire) {
      const cible = !queue.length && !/^\s*\[?divider|^Cr[ée]neaux/.test(ligne) ? garde : queue;
      cible.push(ligne);
    }
    sections.itineraire = garde;
    sections.fin = queue.concat(sections.fin);
  }
  return sections;
}

// --- Parsing du corps ------------------------------------------------------------------

function parseAdresseZone(lignes, mot) {
  const motif = new RegExp(`^\\s*${mot}\\s*:`, 'i');
  for (const ligne of lignes) {
    if (ligne.startsWith('###')) continue;
    if (motif.test(sansAccents(ligne))) {
      const v = valeurApres(ligne);
      if (v) return v;
    }
  }
  return null;
}

function parseLieu(lignes) {
  const lieu = {
    adresse_brute: null, type_logement: null, etage: null, ascenseur: null,
    ascenseur_petit: null, rdc: false, duplex: false, portage_m: null, monte_meuble: null,
  };
  const alertes = [];
  const portages = [];
  let portageTotal = null;

  for (const ligne of lignes) {
    const nu = sansAccents(ligne);
    if (nu.includes('duplex')) lieu.duplex = true;
    if (coche(ligne)) {
      const lib = sansAccents(libelleCase(ligne));
      if (lib.startsWith('maison')) lieu.type_logement = 'maison';
      else if (lib.startsWith('appartement')) lieu.type_logement = 'appartement';
      else if (lib.startsWith('rdc')) lieu.rdc = true;
      else if (lib.startsWith('grand')) { lieu.ascenseur = true; lieu.ascenseur_petit = false; }
      else if (lib.startsWith('petit')) { lieu.ascenseur = true; lieu.ascenseur_petit = true; }
      continue;
    }
    if (nu.includes('etage avec ascenseur')) {
      lieu.ascenseur = true;
      const e = nbEtage(valeurApres(ligne));
      if (e !== null) lieu.etage = e;
    } else if (nu.includes('etage sans ascenseur')) {
      const e = nbEtage(valeurApres(ligne));
      if (lieu.ascenseur === null) {
        lieu.ascenseur = false;
        if (e !== null) lieu.etage = e;
      }
    } else if (nu.includes('monte-meuble') || nu.includes('monte meuble') || nu.includes('monte-charge')) {
      lieu.monte_meuble = /\b2\s*h/.test(nu) ? '2h' : nu.includes('demi') ? 'demi' : null;
    } else if (/^\s*-?\s*(entree|interieur)\s*\(/.test(nu)) {
      const v = valeurApres(ligne);
      const n = nombres(v);
      if (sansAccents(v).includes('portage total')) {
        if (n.length) portageTotal = Math.max(portageTotal || 0, Math.max(...n));
      } else {
        portages.push(n.length ? Math.max(...n) : null);
      }
      if (v.includes('🟡')) alertes.push(ligne.trim());
    } else if (nu.startsWith('distance de portage') && valeurApres(ligne)) {
      const n = nombres(valeurApres(ligne));
      if (n.length) portageTotal = Math.max(portageTotal || 0, Math.max(...n));
    } else if (ligne.includes('🟡')) {
      alertes.push(ligne.trim());
    }
  }

  if (portageTotal !== null) lieu.portage_m = portageTotal;
  else {
    const connus = portages.filter((p) => p !== null);
    if (connus.length) lieu.portage_m = connus.reduce((a, b) => a + b, 0);
  }
  if (lieu.duplex) lieu.type_logement = lieu.type_logement || 'appartement';

  if (lieu.type_logement === null) {
    const texte = sansAccents(lignes.join(' '));
    if (/garde[- ]meuble|box\b|depot|stockage|local ?box/.test(texte)) {
      lieu.type_logement = 'garde-meuble';
      if (texte.includes('saint-loubes') || texte.includes('saint loubes')) {
        lieu.rdc = true;
        lieu.etage = 0;
        if (lieu.ascenseur === null) lieu.ascenseur = false;
      }
    }
  }
  return [lieu, alertes];
}

// Sous-ensemble de parser_corps utile au groupage : contact, lieux, volume, date, notes.
// (Le chiffrage fin — matériel, cartons, démontage — reste l'affaire du calculateur de devis.)
function parserCorps(lignes) {
  const sections = decouper(lignes);
  const alertes = [];

  const client = { nom: null, prenom: null, tel: null, email: null };
  for (const ligne of sections.entete) {
    const nu = sansAccents(ligne);
    if (nu.startsWith('telephone') || nu.startsWith('tel ')) client.tel = valeurApres(ligne) || null;
    else if (nu.startsWith('mail') || nu.startsWith('e-mail') || nu.startsWith('email')) client.email = valeurApres(ligne) || null;
  }

  const [depart, alD] = parseLieu(sections.depart);
  const [arrivee, alA] = parseLieu(sections.arrivee);
  alertes.push(...alD.map((a) => 'Départ — ' + a), ...alA.map((a) => 'Arrivée — ' + a));
  depart.adresse_brute = parseAdresseZone(sections.entete, 'depart');
  arrivee.adresse_brute = parseAdresseZone(sections.entete, 'arrivee');

  const mission = { volume_m3: null, date_intervention: null, reservation_parking: [] };
  for (const ligne of sections.offre) {
    const nu = sansAccents(ligne);
    if (coche(ligne)) {
      const lib = sansAccents(libelleCase(ligne));
      if (lib.startsWith('au depart')) mission.reservation_parking.push('départ');
      else if (lib.startsWith("a l'arrivee") || lib.startsWith('a l arrivee')) mission.reservation_parking.push('arrivée');
      continue;
    }
    if (nu.includes('volume de meuble')) {
      const avant = ligne.split('|')[0];
      const [vol, alerte] = lireVolume(avant.replace(/^.*volume de meuble\s*:/i, ''));
      mission.volume_m3 = vol;
      if (alerte) alertes.push(alerte);
      if (ligne.includes('🟡')) alertes.push(ligne.trim());
    } else if (nu.includes('date / heure') || nu.startsWith('date /')) {
      mission.date_intervention = valeurApres(ligne) || null;
      if (ligne.includes('🟡')) alertes.push(ligne.trim());
    }
  }

  const notes = [];
  let dansNotes = false;
  for (const ligne of sections.fin) {
    const nu = sansAccents(ligne);
    if (nu.startsWith('notes')) {
      dansNotes = true;
      const reste = valeurApres(ligne);
      if (reste) notes.push(reste);
      continue;
    }
    if (/^\s*(temps de mission|temps de trajet|transport\s*:|rdv acompte|\[divider)/.test(nu)) dansNotes = false;
    if (dansNotes && ligne.trim()) notes.push(ligne.trim());
  }
  alertes.push(...notes.filter((l) => l.includes('🟡')));

  return { client, depart, arrivee, mission, notes, alertes: [...new Set(alertes)].sort() };
}

// --- Notion : propriétés et blocs ------------------------------------------------------

const texteRiche = (rich) => (rich || []).map((x) => x.plain_text || '').join('');

function valeurPropriete(prop) {
  if (!prop) return null;
  const type = prop.type;
  const brut = prop[type];
  if (type === 'rich_text' || type === 'title') return texteRiche(brut) || null;
  if (type === 'number' || type === 'checkbox') return brut ?? null;
  if (type === 'select') return brut ? brut.name : null;
  if (type === 'date') return brut ? brut.start : null;
  if (type === 'email' || type === 'url' || type === 'phone_number') return brut || null;
  if (type === 'unique_id') {
    if (brut && brut.prefix) return `${brut.prefix}-${brut.number}`;
    return (brut || {}).number ?? null;
  }
  return null;
}

// Blocs Notion (listes `results` de /blocks/{id}/children) → lignes, comme lire_corps.
// `enfants` : { idBloc: [blocs] } pour les blocs `has_children` déjà lus.
function lignesDepuisBlocs(blocs, enfants = {}, profondeur = 0) {
  const lignes = [];
  for (const b of blocs || []) {
    const type = b.type;
    const contenu = b[type] || {};
    let texte = texteRiche(contenu.rich_text);
    let prefixe = '';
    if (type === 'to_do') prefixe = contenu.checked ? '- [x] ' : '- [ ] ';
    else if (type === 'heading_1' || type === 'heading_2' || type === 'heading_3') prefixe = '### ';
    else if (type === 'bulleted_list_item' || type === 'numbered_list_item') prefixe = '- ';
    else if (!['paragraph', 'quote', 'callout', 'toggle'].includes(type)) texte = texte || `[${type}]`;
    texte.split('\n').forEach((sous, i) => lignes.push('  '.repeat(profondeur) + (i === 0 ? prefixe : '') + sous));
    if (b.has_children && type !== 'child_database' && enfants[b.id]) {
      lignes.push(...lignesDepuisBlocs(enfants[b.id], enfants, profondeur + 1));
    }
  }
  return lignes;
}

// Repli : une propriété ne comble qu'un champ ABSENT du corps, jamais ne l'écrase (croiser()).
const REPLIS = [
  ['mission', 'volume_m3', 'Volume (m3)'],
  ['depart', 'adresse_brute', 'Adresse départ'],
  ['arrivee', 'adresse_brute', 'Adresse arrivée'],
  ['depart', 'type_logement', 'Départ - type logement'],
  ['arrivee', 'type_logement', 'Arrivée - type logement'],
  ['depart', 'rdc', 'Départ - RDC'],
  ['arrivee', 'rdc', 'Arrivée - RDC'],
  ['depart', 'portage_m', 'Départ - distance portage'],
  ['arrivee', 'portage_m', 'Arrivée - distance portage'],
  ['client', 'tel', 'Téléphone'],
  ['client', 'email', 'Email'],
];

const vide = (v) => v === null || v === undefined || v === '' || (Array.isArray(v) && !v.length);

function completerParProprietes(fiche, proprietes) {
  for (const [bloc, champ, nomProp] of REPLIS) {
    let v = valeurPropriete((proprietes || {})[nomProp]);
    if (vide(v)) continue;
    fiche[bloc] = fiche[bloc] || {};
    if (!vide(fiche[bloc][champ])) continue;
    if (champ === 'type_logement') v = String(v).toLowerCase();
    if (champ === 'portage_m') {
      const n = nombres(String(v));
      v = n.length ? n.reduce((a, b) => a + b, 0) : null;
    }
    if (v !== null) fiche[bloc][champ] = v;
  }
  return fiche;
}

function nomPrenomTitre(titre) {
  const mots = String(titre || '').replace(/\s*\d{2}\/\d{2}(\/\d{2,4})?\s*$/, '').trim().split(/\s+/).filter(Boolean);
  let prise = 0;
  for (const m of mots) {
    if (m === m.toUpperCase() && /\p{L}/u.test(m)) prise++;
    else break;
  }
  const nom = mots.slice(0, prise).join(' ') || mots[0] || null;
  const prenom = mots.slice(prise).join(' ') || null;
  return [nom, prenom];
}

// --- noCRM -----------------------------------------------------------------------------

const BRUIT_TITRE = /\s*(\(.*?\)|[-–—]\s*(bx|bordeaux|paris|axe|idf|fin|debut|mi)[^-–—]*)\s*/gi;

function nomProbable(titre) {
  return String(titre || '').replace(BRUIT_TITRE, ' ').trim().replace(/^[\s\-–—]+|[\s\-–—]+$/g, '');
}

function motsDuNom(titre) {
  return nomProbable(titre).split(/[^\p{L}\p{N}_]+/u).filter((m) => m.length >= 3);
}

function enteteContact(description) {
  const contact = { prenom: null, nom: null, tel: null, email: null };
  for (const ligne of String(description || '').split('\n')) {
    if (ligne.trim() === '---') break;
    const i = ligne.indexOf(':');
    if (i < 0) continue;
    const cle = sansAccents(ligne.slice(0, i)).trim();
    const valeur = ligne.slice(i + 1).trim();
    if (!valeur) continue;
    if (cle === 'prenom') contact.prenom = valeur;
    else if (cle === 'nom') contact.nom = valeur;
    else if (cle.startsWith('telephone') || cle === 'tel') contact.tel = valeur;
    else if (['e-mail', 'email', 'mail'].includes(cle)) contact.email = valeur;
  }
  return contact;
}

function corpsDuLead(description) {
  const d = String(description || '');
  const i = d.indexOf('\n---\n');
  return (i >= 0 ? d.slice(i + 5) : d).split('\n').map((l) => l.trimEnd());
}

// Choisit la fiche Notion d'une opportunité parmi les candidats trouvés par mot.
// Rend [page, raison] — page null si rien de sûr : mieux vaut un dossier signalé qu'apparié au mauvais client.
function choisirFiche(titreLead, candidats) {
  const nom = nomProbable(titreLead);
  const mots = motsDuNom(titreLead);
  if (!mots.length) return [null, 'titre noCRM illisible'];
  const uniques = [...new Map((candidats || []).map((p) => [p.id, p])).values()];
  if (!uniques.length) return [null, `aucune fiche Notion pour « ${nom} »`];
  if (uniques.length === 1) return [uniques[0], null];
  const cles = new Set(mots.map((m) => m.toLowerCase()));
  const exacts = uniques.filter((p) => {
    const jetons = new Set(String(valeurPropriete(p.properties['Nom client']) || '').split(/[^\p{L}\p{N}_]+/u).map((j) => j.toLowerCase()));
    return [...cles].every((c) => jetons.has(c));
  });
  if (exacts.length === 1) return [exacts[0], null];
  const titres = uniques.map((p) => valeurPropriete(p.properties['Nom client']) || '?').join(', ');
  return [null, `${uniques.length} fiches Notion possibles pour « ${nom} » (${titres})`];
}

// --- Adresses --------------------------------------------------------------------------

const ADRESSE_VILLE_EN_TETE = /^\s*([^(\n]+?)\s*\((\d{5})\)\s*[—–-]\s*(.+)$/;
const BRUIT_ADRESSE = /\s*\((?:[^()]*(?:verifier|preciser|livraison|environ|selon)[^()]*)\)|\s*🟡[^,]*/giu;

// La BAN a besoin de la rue en tête : « Cenon (33150) — 20 Av. Jean Jaurès » → « 20 Av. Jean Jaurès, 33150 Cenon ».
function normaliserAdresse(brute) {
  if (!brute) return null;
  let texte = String(brute).replace(BRUIT_ADRESSE, '').replace(/^[\s,;—–-]+|[\s,;—–-]+$/g, '');
  const m = texte.match(ADRESSE_VILLE_EN_TETE);
  if (m) {
    const rue = m[3].replace(/^[\s,;]+|[\s,;]+$/g, '');
    const cp = m[2];
    const ville = m[1].trim();
    texte = rue.includes(cp) ? rue : `${rue}, ${cp} ${ville}`;
  }
  texte = texte.split(/\s+/).filter(Boolean).join(' ');
  return texte || null;
}

function porteUnNumero(adresse) {
  const sansCp = String(adresse || '').replace(/\b\d{5}\b/g, ' ');
  return /\b\d{1,4}\s*(bis|ter|[a-d])?\b/i.test(sansCp);
}

function departement(adresse) {
  const cps = String(adresse || '').match(/\b\d{5}\b/g);
  return cps ? cps[cps.length - 1].slice(0, 2) : null;
}

function sensDossier(adresseDepart, adresseArrivee) {
  const d = departement(adresseDepart);
  const a = departement(adresseArrivee);
  if (DEPTS_IDF.includes(a) && !DEPTS_IDF.includes(d)) return 'aller';
  if (DEPTS_IDF.includes(d) && !DEPTS_IDF.includes(a)) return 'retour';
  return null;
}

function stockeAuDepot(mission, lieu) {
  const texte = sansAccents(JSON.stringify(lieu || {}));
  if (texte.includes('saint-loubes') || texte.includes('saint loubes')) return true;
  return Boolean((mission || {}).garde_meuble) && texte.includes('loubes');
}

// --- Assemblage ------------------------------------------------------------------------

// lead : opportunité noCRM · page : fiche Notion (avec `properties`) ou null · lignes : corps
// de la fiche (lignesDepuisBlocs) · souci : raison pour laquelle aucune fiche n'a été retenue.
function batirDossier(lead, page, lignes, souci) {
  const manques = [];
  const contact = enteteContact(lead.description);
  let fiche = null;
  let proprietes = {};
  let source = null;

  if (page && lignes && lignes.length) {
    fiche = parserCorps(lignes);
    proprietes = page.properties || {};
    const [nomT, prenomT] = nomPrenomTitre(valeurPropriete(proprietes['Nom client']) || '');
    fiche.client.nom = fiche.client.nom || nomT;
    fiche.client.prenom = fiche.client.prenom || prenomT;
    completerParProprietes(fiche, proprietes);
    fiche.mission.date_chargement = valeurPropriete(proprietes['Date de chargement']);
    source = 'notion';
  }
  if (!fiche) {
    if (souci) manques.push(souci);
    const corps = corpsDuLead(lead.description);
    if (corps.length > 5) {
      fiche = parserCorps(corps);
      source = 'nocrm';
      manques.push('dossier lu dans la description noCRM, pas dans Notion');
    } else {
      fiche = { client: {}, mission: {}, depart: {}, arrivee: {}, notes: [], alertes: [] };
      source = 'aucune';
      manques.push('ni fiche Notion ni corps exploitable dans noCRM');
    }
  }

  const client = fiche.client || {};
  const mission = fiche.mission || {};
  const depart = fiche.depart || {};
  const arrivee = fiche.arrivee || {};
  const nom = contact.nom || client.nom || nomProbable(lead.title);
  const prenom = contact.prenom || client.prenom || '';

  const adresseDepart = normaliserAdresse(depart.adresse_brute);
  const adresseArrivee = normaliserAdresse(arrivee.adresse_brute);
  if (!adresseDepart) manques.push('adresse de depart absente');
  else if (!porteUnNumero(adresseDepart)) manques.push('adresse de depart sans numero de rue — a faire preciser au client');
  if (!adresseArrivee) manques.push("adresse d'arrivee absente");
  else if (!porteUnNumero(adresseArrivee)) manques.push("adresse d'arrivee sans numero de rue — a faire preciser au client");

  const volume = mission.volume_m3 || valeurPropriete(proprietes['Volume (m3)']);
  if (!volume) {
    manques.push('volume absent — la colonne est APRES « Devis envoye », le volume devrait etre ferme : fiche a resynchroniser');
  }

  const sens = sensDossier(adresseDepart, adresseArrivee);
  if (sens === null && adresseDepart && adresseArrivee) manques.push('sens indetermine (ni depart ni arrivee en Ile-de-France)');

  let fenetre = { tot: null, tard: null };
  const dc = (proprietes['Date de chargement'] || {}).date;
  if (dc && dc.start) fenetre = { tot: dc.start.slice(0, 10), tard: (dc.end || dc.start).slice(0, 10) };
  if (!fenetre.tot) fenetre = { tot: mission.date_chargement || null, tard: mission.date_chargement || null };
  if (!fenetre.tot) manques.push('fenetre de chargement absente');

  const chiffres = {
    ttc: valeurPropriete(proprietes['Prix Total TTC']),
    transport_ht: valeurPropriete(proprietes['Transport HT']),
    deplacement_ht: valeurPropriete(proprietes['Déplacement HT']),
  };
  if (!chiffres.ttc) chiffres.ttc = lead.amount ?? null;
  if (!chiffres.transport_ht) manques.push('ligne Transport HT absente — marge de tournee non calculable sur ce dossier');

  return {
    nocrm_id: lead.id,
    titre_nocrm: lead.title,
    ref: valeurPropriete(proprietes['Réf']),
    nom,
    prenom,
    nom_complet: `${prenom} ${nom}`.trim(),
    email: contact.email || client.email || null,
    tel: contact.tel || client.tel || null,
    sens,
    volume_m3: volume || null,
    depart: { ...depart, adresse: adresseDepart },
    arrivee: { ...arrivee, adresse: adresseArrivee },
    stocke_depot: stockeAuDepot(mission, depart),
    fenetre,
    chiffres,
    date_intervention: mission.date_intervention || null,
    notes: fiche.notes || [],
    alertes: fiche.alertes || [],
    source,
    notion_id: page ? page.id : null,
    notion_url: page ? page.url || null : null,
    manques,
  };
}


const leads = $('Des demandes vivantes ?').all().map((i) => i.json);
const reponses = $input.all().map((i) => i.json);

// Une erreur de Notion n'est PAS « pas de fiche » : on arrête, le gestionnaire d'erreurs alerte.
const enErreur = reponses.filter((r) => r && r.error);
if (enErreur.length) {
  const d = enErreur[0].error.description || enErreur[0].error.message;
  throw new Error('Notion a refusé ' + enErreur.length + ' recherche(s) sur ' + reponses.length + ' — import interrompu. ' + d);
}
return leads.map((entree, i) => {
  const candidats = ((reponses[i] || {}).results) || [];
  const [page, souci] = choisirFiche(entree.lead.title, candidats);
  return { json: { lead: entree.lead, souci: souci || null,
    page: page ? { id: page.id, url: page.url, properties: page.properties } : null,
    pageId: page ? String(page.id).replace(/-/g, '') : null } };
});

const fiches = $('Fiche Notion trouvée ?').all().map((i) => i.json);
const reponses = $input.all().map((i) => i.json);
const sortie = [];
fiches.forEach((f, i) => {
  const blocs = ((reponses[i] || {}).results) || [];
  blocs.filter((b) => b.has_children && b.type !== 'child_database')
    .forEach((b) => sortie.push({ json: { pageId: f.pageId, blocId: b.id } }));
});
// Aucun bloc imbriqué : un item quand même, sinon la chaîne s'arrête (LECONS).
return sortie.length ? sortie : [{ json: { pageId: null, blocId: null } }];

// Lecture d'un dossier de groupage : opportunité noCRM × fiche Notion.
// Portage de Sam'Déménage/outils/Groupage/collecte.py et lib/fiche_notion.py (parser_corps).
// Fonctions pures, sans dépendance : le même fichier sert au nœud Code de WF1 (inséré par
// construire.mjs, mots-clés `export` retirés) et aux tests Node.
// Règle maîtresse : le CORPS de la fiche fait foi, les propriétés ne comblent que ce qu'il ne porte pas.

const DEPTS_IDF = ['75', '77', '78', '91', '92', '93', '94', '95'];

function sansAccents(s) {
  return String(s || '').normalize('NFD').replace(/\p{Mn}/gu, '').toLowerCase();
}

function nombres(s) {
  return (String(s || '').match(/\d+(?:[.,]\d+)?/g) || []).map((x) => parseFloat(x.replace(',', '.')));
}

function premierNombre(s) {
  const n = nombres(s);
  return n.length ? n[0] : null;
}

function nbEtage(s) {
  if (s === null || s === undefined) return null;
  const brut = sansAccents(s).trim();
  if (!brut) return null;
  let m = brut.match(/^\s*r\s*\+\s*(\d+)/);
  if (m) return parseInt(m[1], 10);
  if (/^\s*(rdc|rez|plain[- ]?pied|0\b)/.test(brut)) return 0;
  m = brut.match(/\d+/);
  return m ? parseInt(m[0], 10) : null;
}

const VOLUME = /(\d+(?:[.,]\d+)?)\s*m\s*(?:3|³)/gi;

// Un volume composite n'est jamais réduit à son premier nombre :
// « 7 m3 + 40 m3 = 47 m3 total » vaut 47 ; plusieurs volumes sans total → null + alerte.
function lireVolume(texte) {
  const trouves = [...String(texte || '').matchAll(VOLUME)].map((m) => [m.index, parseFloat(m[1].replace(',', '.'))]);
  if (!trouves.length) return [null, null];
  if (trouves.length === 1) return [trouves[0][1], null];
  const nu = sansAccents(texte);
  const reperes = [...nu.matchAll(/total|=/g)].map((m) => m.index);
  const liste = trouves.map((t) => t[1]);
  if (reperes.length) {
    let meilleur = trouves[0];
    let dist = Infinity;
    for (const t of trouves) {
      const d = Math.min(...reperes.map((r) => Math.abs(t[0] - r)));
      if (d < dist) { dist = d; meilleur = t; }
    }
    return [meilleur[1], `Volume composite dans la fiche (${liste.join(' + ')} m³) — total retenu : ${meilleur[1]} m³.`];
  }
  return [null, `Volume composite non tranché (${liste.join(' / ')} m³) : aucun total indiqué dans la fiche.`];
}

function valeurApres(ligne) {
  const i = ligne.indexOf(':');
  return i >= 0 ? ligne.slice(i + 1).trim() : '';
}

const coche = (ligne) => ligne.trimStart().startsWith('- [x]');
const libelleCase = (ligne) => ligne.replace(/^\s*-\s*\[[ x]\]\s*/, '');

// --- Découpage en sections -------------------------------------------------------------

const SECTIONS = [
  ['entete', null],
  ['offre', /details? offre/],
  ['depart', /^depart\b/],
  ['arrivee', /^arrivee\b/],
  ['demontage', /meubles? a demonter/],
  ['cartons', /mise en cartons?/],
  ['materiel', /materiel a livrer/],
  ['lourds', /meubles? lourds?/],
  ['itineraire', /itineraires?/],
];

function decouper(lignes) {
  const sections = { fin: [] };
  for (const [nom] of SECTIONS) sections[nom] = [];
  let courante = 'entete';
  for (const ligne of lignes) {
    if (ligne.startsWith('###')) {
      const titre = sansAccents(ligne.replace(/^[#\s]+/, '').trim());
      const trouve = SECTIONS.find(([, motif]) => motif && motif.test(titre));
      if (trouve) {
        courante = trouve[0];
        sections[courante].push(ligne);
        continue;
      }
      courante = 'fin';
    }
    sections[courante].push(ligne);
  }
  if (sections.itineraire.length) {
    const garde = [];
    const queue = [];
    for (const ligne of sections.itineraire) {
      const cible = !queue.length && !/^\s*\[?divider|^Cr[ée]neaux/.test(ligne) ? garde : queue;
      cible.push(ligne);
    }
    sections.itineraire = garde;
    sections.fin = queue.concat(sections.fin);
  }
  return sections;
}

// --- Parsing du corps ------------------------------------------------------------------

function parseAdresseZone(lignes, mot) {
  const motif = new RegExp(`^\\s*${mot}\\s*:`, 'i');
  for (const ligne of lignes) {
    if (ligne.startsWith('###')) continue;
    if (motif.test(sansAccents(ligne))) {
      const v = valeurApres(ligne);
      if (v) return v;
    }
  }
  return null;
}

function parseLieu(lignes) {
  const lieu = {
    adresse_brute: null, type_logement: null, etage: null, ascenseur: null,
    ascenseur_petit: null, rdc: false, duplex: false, portage_m: null, monte_meuble: null,
  };
  const alertes = [];
  const portages = [];
  let portageTotal = null;

  for (const ligne of lignes) {
    const nu = sansAccents(ligne);
    if (nu.includes('duplex')) lieu.duplex = true;
    if (coche(ligne)) {
      const lib = sansAccents(libelleCase(ligne));
      if (lib.startsWith('maison')) lieu.type_logement = 'maison';
      else if (lib.startsWith('appartement')) lieu.type_logement = 'appartement';
      else if (lib.startsWith('rdc')) lieu.rdc = true;
      else if (lib.startsWith('grand')) { lieu.ascenseur = true; lieu.ascenseur_petit = false; }
      else if (lib.startsWith('petit')) { lieu.ascenseur = true; lieu.ascenseur_petit = true; }
      continue;
    }
    if (nu.includes('etage avec ascenseur')) {
      lieu.ascenseur = true;
      const e = nbEtage(valeurApres(ligne));
      if (e !== null) lieu.etage = e;
    } else if (nu.includes('etage sans ascenseur')) {
      const e = nbEtage(valeurApres(ligne));
      if (lieu.ascenseur === null) {
        lieu.ascenseur = false;
        if (e !== null) lieu.etage = e;
      }
    } else if (nu.includes('monte-meuble') || nu.includes('monte meuble') || nu.includes('monte-charge')) {
      lieu.monte_meuble = /\b2\s*h/.test(nu) ? '2h' : nu.includes('demi') ? 'demi' : null;
    } else if (/^\s*-?\s*(entree|interieur)\s*\(/.test(nu)) {
      const v = valeurApres(ligne);
      const n = nombres(v);
      if (sansAccents(v).includes('portage total')) {
        if (n.length) portageTotal = Math.max(portageTotal || 0, Math.max(...n));
      } else {
        portages.push(n.length ? Math.max(...n) : null);
      }
      if (v.includes('🟡')) alertes.push(ligne.trim());
    } else if (nu.startsWith('distance de portage') && valeurApres(ligne)) {
      const n = nombres(valeurApres(ligne));
      if (n.length) portageTotal = Math.max(portageTotal || 0, Math.max(...n));
    } else if (ligne.includes('🟡')) {
      alertes.push(ligne.trim());
    }
  }

  if (portageTotal !== null) lieu.portage_m = portageTotal;
  else {
    const connus = portages.filter((p) => p !== null);
    if (connus.length) lieu.portage_m = connus.reduce((a, b) => a + b, 0);
  }
  if (lieu.duplex) lieu.type_logement = lieu.type_logement || 'appartement';

  if (lieu.type_logement === null) {
    const texte = sansAccents(lignes.join(' '));
    if (/garde[- ]meuble|box\b|depot|stockage|local ?box/.test(texte)) {
      lieu.type_logement = 'garde-meuble';
      if (texte.includes('saint-loubes') || texte.includes('saint loubes')) {
        lieu.rdc = true;
        lieu.etage = 0;
        if (lieu.ascenseur === null) lieu.ascenseur = false;
      }
    }
  }
  return [lieu, alertes];
}

// Sous-ensemble de parser_corps utile au groupage : contact, lieux, volume, date, notes.
// (Le chiffrage fin — matériel, cartons, démontage — reste l'affaire du calculateur de devis.)
function parserCorps(lignes) {
  const sections = decouper(lignes);
  const alertes = [];

  const client = { nom: null, prenom: null, tel: null, email: null };
  for (const ligne of sections.entete) {
    const nu = sansAccents(ligne);
    if (nu.startsWith('telephone') || nu.startsWith('tel ')) client.tel = valeurApres(ligne) || null;
    else if (nu.startsWith('mail') || nu.startsWith('e-mail') || nu.startsWith('email')) client.email = valeurApres(ligne) || null;
  }

  const [depart, alD] = parseLieu(sections.depart);
  const [arrivee, alA] = parseLieu(sections.arrivee);
  alertes.push(...alD.map((a) => 'Départ — ' + a), ...alA.map((a) => 'Arrivée — ' + a));
  depart.adresse_brute = parseAdresseZone(sections.entete, 'depart');
  arrivee.adresse_brute = parseAdresseZone(sections.entete, 'arrivee');

  const mission = { volume_m3: null, date_intervention: null, reservation_parking: [] };
  for (const ligne of sections.offre) {
    const nu = sansAccents(ligne);
    if (coche(ligne)) {
      const lib = sansAccents(libelleCase(ligne));
      if (lib.startsWith('au depart')) mission.reservation_parking.push('départ');
      else if (lib.startsWith("a l'arrivee") || lib.startsWith('a l arrivee')) mission.reservation_parking.push('arrivée');
      continue;
    }
    if (nu.includes('volume de meuble')) {
      const avant = ligne.split('|')[0];
      const [vol, alerte] = lireVolume(avant.replace(/^.*volume de meuble\s*:/i, ''));
      mission.volume_m3 = vol;
      if (alerte) alertes.push(alerte);
      if (ligne.includes('🟡')) alertes.push(ligne.trim());
    } else if (nu.includes('date / heure') || nu.startsWith('date /')) {
      mission.date_intervention = valeurApres(ligne) || null;
      if (ligne.includes('🟡')) alertes.push(ligne.trim());
    }
  }

  const notes = [];
  let dansNotes = false;
  for (const ligne of sections.fin) {
    const nu = sansAccents(ligne);
    if (nu.startsWith('notes')) {
      dansNotes = true;
      const reste = valeurApres(ligne);
      if (reste) notes.push(reste);
      continue;
    }
    if (/^\s*(temps de mission|temps de trajet|transport\s*:|rdv acompte|\[divider)/.test(nu)) dansNotes = false;
    if (dansNotes && ligne.trim()) notes.push(ligne.trim());
  }
  alertes.push(...notes.filter((l) => l.includes('🟡')));

  return { client, depart, arrivee, mission, notes, alertes: [...new Set(alertes)].sort() };
}

// --- Notion : propriétés et blocs ------------------------------------------------------

const texteRiche = (rich) => (rich || []).map((x) => x.plain_text || '').join('');

function valeurPropriete(prop) {
  if (!prop) return null;
  const type = prop.type;
  const brut = prop[type];
  if (type === 'rich_text' || type === 'title') return texteRiche(brut) || null;
  if (type === 'number' || type === 'checkbox') return brut ?? null;
  if (type === 'select') return brut ? brut.name : null;
  if (type === 'date') return brut ? brut.start : null;
  if (type === 'email' || type === 'url' || type === 'phone_number') return brut || null;
  if (type === 'unique_id') {
    if (brut && brut.prefix) return `${brut.prefix}-${brut.number}`;
    return (brut || {}).number ?? null;
  }
  return null;
}

// Blocs Notion (listes `results` de /blocks/{id}/children) → lignes, comme lire_corps.
// `enfants` : { idBloc: [blocs] } pour les blocs `has_children` déjà lus.
function lignesDepuisBlocs(blocs, enfants = {}, profondeur = 0) {
  const lignes = [];
  for (const b of blocs || []) {
    const type = b.type;
    const contenu = b[type] || {};
    let texte = texteRiche(contenu.rich_text);
    let prefixe = '';
    if (type === 'to_do') prefixe = contenu.checked ? '- [x] ' : '- [ ] ';
    else if (type === 'heading_1' || type === 'heading_2' || type === 'heading_3') prefixe = '### ';
    else if (type === 'bulleted_list_item' || type === 'numbered_list_item') prefixe = '- ';
    else if (!['paragraph', 'quote', 'callout', 'toggle'].includes(type)) texte = texte || `[${type}]`;
    texte.split('\n').forEach((sous, i) => lignes.push('  '.repeat(profondeur) + (i === 0 ? prefixe : '') + sous));
    if (b.has_children && type !== 'child_database' && enfants[b.id]) {
      lignes.push(...lignesDepuisBlocs(enfants[b.id], enfants, profondeur + 1));
    }
  }
  return lignes;
}

// Repli : une propriété ne comble qu'un champ ABSENT du corps, jamais ne l'écrase (croiser()).
const REPLIS = [
  ['mission', 'volume_m3', 'Volume (m3)'],
  ['depart', 'adresse_brute', 'Adresse départ'],
  ['arrivee', 'adresse_brute', 'Adresse arrivée'],
  ['depart', 'type_logement', 'Départ - type logement'],
  ['arrivee', 'type_logement', 'Arrivée - type logement'],
  ['depart', 'rdc', 'Départ - RDC'],
  ['arrivee', 'rdc', 'Arrivée - RDC'],
  ['depart', 'portage_m', 'Départ - distance portage'],
  ['arrivee', 'portage_m', 'Arrivée - distance portage'],
  ['client', 'tel', 'Téléphone'],
  ['client', 'email', 'Email'],
];

const vide = (v) => v === null || v === undefined || v === '' || (Array.isArray(v) && !v.length);

function completerParProprietes(fiche, proprietes) {
  for (const [bloc, champ, nomProp] of REPLIS) {
    let v = valeurPropriete((proprietes || {})[nomProp]);
    if (vide(v)) continue;
    fiche[bloc] = fiche[bloc] || {};
    if (!vide(fiche[bloc][champ])) continue;
    if (champ === 'type_logement') v = String(v).toLowerCase();
    if (champ === 'portage_m') {
      const n = nombres(String(v));
      v = n.length ? n.reduce((a, b) => a + b, 0) : null;
    }
    if (v !== null) fiche[bloc][champ] = v;
  }
  return fiche;
}

function nomPrenomTitre(titre) {
  const mots = String(titre || '').replace(/\s*\d{2}\/\d{2}(\/\d{2,4})?\s*$/, '').trim().split(/\s+/).filter(Boolean);
  let prise = 0;
  for (const m of mots) {
    if (m === m.toUpperCase() && /\p{L}/u.test(m)) prise++;
    else break;
  }
  const nom = mots.slice(0, prise).join(' ') || mots[0] || null;
  const prenom = mots.slice(prise).join(' ') || null;
  return [nom, prenom];
}

// --- noCRM -----------------------------------------------------------------------------

const BRUIT_TITRE = /\s*(\(.*?\)|[-–—]\s*(bx|bordeaux|paris|axe|idf|fin|debut|mi)[^-–—]*)\s*/gi;

function nomProbable(titre) {
  return String(titre || '').replace(BRUIT_TITRE, ' ').trim().replace(/^[\s\-–—]+|[\s\-–—]+$/g, '');
}

function motsDuNom(titre) {
  return nomProbable(titre).split(/[^\p{L}\p{N}_]+/u).filter((m) => m.length >= 3);
}

function enteteContact(description) {
  const contact = { prenom: null, nom: null, tel: null, email: null };
  for (const ligne of String(description || '').split('\n')) {
    if (ligne.trim() === '---') break;
    const i = ligne.indexOf(':');
    if (i < 0) continue;
    const cle = sansAccents(ligne.slice(0, i)).trim();
    const valeur = ligne.slice(i + 1).trim();
    if (!valeur) continue;
    if (cle === 'prenom') contact.prenom = valeur;
    else if (cle === 'nom') contact.nom = valeur;
    else if (cle.startsWith('telephone') || cle === 'tel') contact.tel = valeur;
    else if (['e-mail', 'email', 'mail'].includes(cle)) contact.email = valeur;
  }
  return contact;
}

function corpsDuLead(description) {
  const d = String(description || '');
  const i = d.indexOf('\n---\n');
  return (i >= 0 ? d.slice(i + 5) : d).split('\n').map((l) => l.trimEnd());
}

// Choisit la fiche Notion d'une opportunité parmi les candidats trouvés par mot.
// Rend [page, raison] — page null si rien de sûr : mieux vaut un dossier signalé qu'apparié au mauvais client.
function choisirFiche(titreLead, candidats) {
  const nom = nomProbable(titreLead);
  const mots = motsDuNom(titreLead);
  if (!mots.length) return [null, 'titre noCRM illisible'];
  const uniques = [...new Map((candidats || []).map((p) => [p.id, p])).values()];
  if (!uniques.length) return [null, `aucune fiche Notion pour « ${nom} »`];
  if (uniques.length === 1) return [uniques[0], null];
  const cles = new Set(mots.map((m) => m.toLowerCase()));
  const exacts = uniques.filter((p) => {
    const jetons = new Set(String(valeurPropriete(p.properties['Nom client']) || '').split(/[^\p{L}\p{N}_]+/u).map((j) => j.toLowerCase()));
    return [...cles].every((c) => jetons.has(c));
  });
  if (exacts.length === 1) return [exacts[0], null];
  const titres = uniques.map((p) => valeurPropriete(p.properties['Nom client']) || '?').join(', ');
  return [null, `${uniques.length} fiches Notion possibles pour « ${nom} » (${titres})`];
}

// --- Adresses --------------------------------------------------------------------------

const ADRESSE_VILLE_EN_TETE = /^\s*([^(\n]+?)\s*\((\d{5})\)\s*[—–-]\s*(.+)$/;
const BRUIT_ADRESSE = /\s*\((?:[^()]*(?:verifier|preciser|livraison|environ|selon)[^()]*)\)|\s*🟡[^,]*/giu;

// La BAN a besoin de la rue en tête : « Cenon (33150) — 20 Av. Jean Jaurès » → « 20 Av. Jean Jaurès, 33150 Cenon ».
function normaliserAdresse(brute) {
  if (!brute) return null;
  let texte = String(brute).replace(BRUIT_ADRESSE, '').replace(/^[\s,;—–-]+|[\s,;—–-]+$/g, '');
  const m = texte.match(ADRESSE_VILLE_EN_TETE);
  if (m) {
    const rue = m[3].replace(/^[\s,;]+|[\s,;]+$/g, '');
    const cp = m[2];
    const ville = m[1].trim();
    texte = rue.includes(cp) ? rue : `${rue}, ${cp} ${ville}`;
  }
  texte = texte.split(/\s+/).filter(Boolean).join(' ');
  return texte || null;
}

function porteUnNumero(adresse) {
  const sansCp = String(adresse || '').replace(/\b\d{5}\b/g, ' ');
  return /\b\d{1,4}\s*(bis|ter|[a-d])?\b/i.test(sansCp);
}

function departement(adresse) {
  const cps = String(adresse || '').match(/\b\d{5}\b/g);
  return cps ? cps[cps.length - 1].slice(0, 2) : null;
}

function sensDossier(adresseDepart, adresseArrivee) {
  const d = departement(adresseDepart);
  const a = departement(adresseArrivee);
  if (DEPTS_IDF.includes(a) && !DEPTS_IDF.includes(d)) return 'aller';
  if (DEPTS_IDF.includes(d) && !DEPTS_IDF.includes(a)) return 'retour';
  return null;
}

function stockeAuDepot(mission, lieu) {
  const texte = sansAccents(JSON.stringify(lieu || {}));
  if (texte.includes('saint-loubes') || texte.includes('saint loubes')) return true;
  return Boolean((mission || {}).garde_meuble) && texte.includes('loubes');
}

// --- Assemblage ------------------------------------------------------------------------

// lead : opportunité noCRM · page : fiche Notion (avec `properties`) ou null · lignes : corps
// de la fiche (lignesDepuisBlocs) · souci : raison pour laquelle aucune fiche n'a été retenue.
function batirDossier(lead, page, lignes, souci) {
  const manques = [];
  const contact = enteteContact(lead.description);
  let fiche = null;
  let proprietes = {};
  let source = null;

  if (page && lignes && lignes.length) {
    fiche = parserCorps(lignes);
    proprietes = page.properties || {};
    const [nomT, prenomT] = nomPrenomTitre(valeurPropriete(proprietes['Nom client']) || '');
    fiche.client.nom = fiche.client.nom || nomT;
    fiche.client.prenom = fiche.client.prenom || prenomT;
    completerParProprietes(fiche, proprietes);
    fiche.mission.date_chargement = valeurPropriete(proprietes['Date de chargement']);
    source = 'notion';
  }
  if (!fiche) {
    if (souci) manques.push(souci);
    const corps = corpsDuLead(lead.description);
    if (corps.length > 5) {
      fiche = parserCorps(corps);
      source = 'nocrm';
      manques.push('dossier lu dans la description noCRM, pas dans Notion');
    } else {
      fiche = { client: {}, mission: {}, depart: {}, arrivee: {}, notes: [], alertes: [] };
      source = 'aucune';
      manques.push('ni fiche Notion ni corps exploitable dans noCRM');
    }
  }

  const client = fiche.client || {};
  const mission = fiche.mission || {};
  const depart = fiche.depart || {};
  const arrivee = fiche.arrivee || {};
  const nom = contact.nom || client.nom || nomProbable(lead.title);
  const prenom = contact.prenom || client.prenom || '';

  const adresseDepart = normaliserAdresse(depart.adresse_brute);
  const adresseArrivee = normaliserAdresse(arrivee.adresse_brute);
  if (!adresseDepart) manques.push('adresse de depart absente');
  else if (!porteUnNumero(adresseDepart)) manques.push('adresse de depart sans numero de rue — a faire preciser au client');
  if (!adresseArrivee) manques.push("adresse d'arrivee absente");
  else if (!porteUnNumero(adresseArrivee)) manques.push("adresse d'arrivee sans numero de rue — a faire preciser au client");

  const volume = mission.volume_m3 || valeurPropriete(proprietes['Volume (m3)']);
  if (!volume) {
    manques.push('volume absent — la colonne est APRES « Devis envoye », le volume devrait etre ferme : fiche a resynchroniser');
  }

  const sens = sensDossier(adresseDepart, adresseArrivee);
  if (sens === null && adresseDepart && adresseArrivee) manques.push('sens indetermine (ni depart ni arrivee en Ile-de-France)');

  let fenetre = { tot: null, tard: null };
  const dc = (proprietes['Date de chargement'] || {}).date;
  if (dc && dc.start) fenetre = { tot: dc.start.slice(0, 10), tard: (dc.end || dc.start).slice(0, 10) };
  if (!fenetre.tot) fenetre = { tot: mission.date_chargement || null, tard: mission.date_chargement || null };
  if (!fenetre.tot) manques.push('fenetre de chargement absente');

  const chiffres = {
    ttc: valeurPropriete(proprietes['Prix Total TTC']),
    transport_ht: valeurPropriete(proprietes['Transport HT']),
    deplacement_ht: valeurPropriete(proprietes['Déplacement HT']),
  };
  if (!chiffres.ttc) chiffres.ttc = lead.amount ?? null;
  if (!chiffres.transport_ht) manques.push('ligne Transport HT absente — marge de tournee non calculable sur ce dossier');

  return {
    nocrm_id: lead.id,
    titre_nocrm: lead.title,
    ref: valeurPropriete(proprietes['Réf']),
    nom,
    prenom,
    nom_complet: `${prenom} ${nom}`.trim(),
    email: contact.email || client.email || null,
    tel: contact.tel || client.tel || null,
    sens,
    volume_m3: volume || null,
    depart: { ...depart, adresse: adresseDepart },
    arrivee: { ...arrivee, adresse: adresseArrivee },
    stocke_depot: stockeAuDepot(mission, depart),
    fenetre,
    chiffres,
    date_intervention: mission.date_intervention || null,
    notes: fiche.notes || [],
    alertes: fiche.alertes || [],
    source,
    notion_id: page ? page.id : null,
    notion_url: page ? page.url || null : null,
    manques,
  };
}

// Carte des demandes (workflow GroupageDemandes) : quelles demandes de devis sont vivantes,
// comment la table les reflète, et lesquelles tiennent sur la route d'une autre.
// Rien que du calcul : noCRM, Notion, les géocodeurs et Valhalla restent dans le workflow.
// Module autonome — inséré seul dans les nœuds Code, il n'importe rien.

const RAYON_TERRE_KM = 6371;
const JOUR_MS = 86400000;

const REGLAGES_DEMANDES = {
  statutsExclus: ['lost', 'cancelled'],
  inactiviteMaxJours: 14,
  couloirKm: 30,
  fenetreJours: 7,
  // Deux clients de la même ville se chargent dans n'importe quel ordre : on tolère qu'une
  // arrivée soit un peu « avant » le départ le long de la route.
  toleranceSensKm: 5,
};

const nombre = (v) => (v === null || v === undefined || v === '' ? NaN : Number(v));
const aDesCoordonnees = (p) => p && Number.isFinite(nombre(p.lat)) && Number.isFinite(nombre(p.lon));

function distanceKm(a, b) {
  const rad = Math.PI / 180;
  const dLat = (b.lat - a.lat) * rad;
  const dLon = (b.lon - a.lon) * rad;
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(a.lat * rad) * Math.cos(b.lat * rad) * Math.sin(dLon / 2) ** 2;
  return 2 * RAYON_TERRE_KM * Math.asin(Math.min(1, Math.sqrt(h)));
}

// Distance d'un point à la route, et sa position le long d'elle (km depuis le départ).
// Projection plane locale, centrée sur le point : à l'échelle d'un couloir de quelques dizaines
// de kilomètres, l'erreur est négligeable.
function projeterSurTrajet(point, trajet) {
  if (!trajet || !trajet.length) return { ecartKm: Infinity, abscisseKm: 0 };
  if (trajet.length === 1) return { ecartKm: distanceKm(point, trajet[0]), abscisseKm: 0 };
  const kmLat = (Math.PI / 180) * RAYON_TERRE_KM;
  const kmLon = kmLat * Math.cos(point.lat * Math.PI / 180);
  const xy = (p) => ({ x: (p.lon - point.lon) * kmLon, y: (p.lat - point.lat) * kmLat });
  let meilleur = { ecartKm: Infinity, abscisseKm: 0 };
  let parcouru = 0;
  for (let i = 0; i < trajet.length - 1; i++) {
    const a = xy(trajet[i]);
    const b = xy(trajet[i + 1]);
    const dx = b.x - a.x;
    const dy = b.y - a.y;
    const long2 = dx * dx + dy * dy;
    const t = long2 ? Math.max(0, Math.min(1, -(a.x * dx + a.y * dy) / long2)) : 0;
    const ecart = Math.hypot(a.x + t * dx, a.y + t * dy);
    const longueur = Math.sqrt(long2);
    if (ecart < meilleur.ecartKm) meilleur = { ecartKm: ecart, abscisseKm: parcouru + t * longueur };
    parcouru += longueur;
  }
  return meilleur;
}

// Polyligne encodée de Valhalla (précision 6 par défaut) → [{ lat, lon }].
function decoderPolyligne(texte, precision = 6) {
  const facteur = 10 ** precision;
  const points = [];
  let i = 0;
  let lat = 0;
  let lon = 0;
  const suivant = () => {
    let resultat = 0;
    let decalage = 0;
    let octet;
    do {
      octet = texte.charCodeAt(i++) - 63;
      resultat |= (octet & 0x1f) << decalage;
      decalage += 5;
    } while (octet >= 0x20);
    return resultat & 1 ? ~(resultat >> 1) : resultat >> 1;
  };
  while (i < String(texte || '').length) {
    lat += suivant();
    lon += suivant();
    points.push({ lat: lat / facteur, lon: lon / facteur });
  }
  return points;
}

// Allège une route de plusieurs milliers de points : on garde un point dès qu'on s'est
// éloigné de `pasKm` du dernier gardé, plus le dernier. Largement assez pour un couloir.
function allegerTrajet(trajet, pasKm = 2) {
  if (!trajet || trajet.length < 3) return trajet || [];
  const garde = [trajet[0]];
  for (let i = 1; i < trajet.length - 1; i++) {
    if (distanceKm(garde[garde.length - 1], trajet[i]) >= pasKm) garde.push(trajet[i]);
  }
  garde.push(trajet[trajet.length - 1]);
  return garde.map((p) => ({ lat: Math.round(p.lat * 1e5) / 1e5, lon: Math.round(p.lon * 1e5) / 1e5 }));
}

// La route d'une demande : celle rangée par l'import, sinon la ligne droite.
function trajetDe(demande) {
  let t = demande.trajet;
  if (typeof t === 'string' && t) {
    try { t = JSON.parse(t); } catch { t = null; }
  }
  return Array.isArray(t) && t.length > 1 ? t : trajetDroit(demande);
}

// Un dossier est « réalisé » quand son chargement ET sa livraison sont passés : il quitte la
// carte. Chargé mais pas encore livré, il reste (le camion peut encore prendre un complément).
function demandeEnCours(d, aujourdhui) {
  const fin = [d.dateLivraisonFin, d.dateLivraison, d.dateFin, d.dateChargement].map(jourDe).filter((j) => j !== null);
  if (!fin.length) return true;
  return Math.max(...fin) >= jourDe(aujourdhui);
}

function chargementPasse(d, aujourdhui) {
  const plage = plageDe(d);
  return Boolean(plage) && plage[1] < jourDe(aujourdhui);
}

function trajetDroit(demande) {
  const d = pointDepart(demande);
  const a = pointArrivee(demande);
  return d && a ? [d, a] : [];
}

function pointDepart(d) {
  return aDesCoordonnees({ lat: d.latD, lon: d.lonD }) ? { lat: nombre(d.latD), lon: nombre(d.lonD) } : null;
}

function pointArrivee(d) {
  return aDesCoordonnees({ lat: d.latA, lon: d.lonA }) ? { lat: nombre(d.latA), lon: nombre(d.lonA) } : null;
}

// Un dossier est vivant s'il n'est ni perdu ni annulé, et s'il a bougé dans noCRM depuis
// moins de `inactiviteMaxJours`. Sans date d'activité lisible, on ne peut pas le dire vivant.
function demandeActive(lead, maintenant, reglages = REGLAGES_DEMANDES) {
  const exclus = reglages.statutsExclus || REGLAGES_DEMANDES.statutsExclus;
  const maxJours = reglages.inactiviteMaxJours ?? REGLAGES_DEMANDES.inactiviteMaxJours;
  const statut = String(lead.status || '').toLowerCase();
  if (exclus.includes(statut)) return { active: false, raison: `statut ${statut}` };
  const activite = derniereActivite(lead);
  if (!activite) return { active: false, raison: 'aucune date d’activité' };
  const jours = (new Date(maintenant).getTime() - new Date(activite).getTime()) / JOUR_MS;
  if (!(jours < maxJours)) return { active: false, raison: `inactif depuis ${Math.floor(jours)} jours` };
  return { active: true, raison: '' };
}

// noCRM : la date la plus récente entre la dernière modification et le dernier passage d'étape.
function derniereActivite(lead) {
  const dates = [lead.updated_at, lead.moved_to_step_at, lead.last_activity_at, lead.created_at]
    .filter(Boolean).map((d) => new Date(d)).filter((d) => !Number.isNaN(d.getTime()));
  if (!dates.length) return null;
  return new Date(Math.max(...dates.map((d) => d.getTime()))).toISOString();
}

const CHAMPS_DEMANDE = ['leadId', 'nom', 'etape', 'statut', 'derniereActivite', 'volume', 'dateChargement', 'dateFin',
  'depart', 'arrivee', 'latD', 'lonD', 'latA', 'lonA', 'qualiteD', 'qualiteA', 'depD', 'depA',
  'notionUrl', 'nocrmUrl', 'montant', 'sansFiche', 'dateLivraison', 'dateLivraisonFin', 'trajet', 'analyse', 'notesEmpreinte'];

// Une ligne de la table « Groupage · demandes ». `infos` : ce qu'on a lu de la fiche Notion
// (ou de la description noCRM à défaut) ; `points` : le géocodage des deux adresses.
function ligneDemande(lead, infos, points, { nocrmBase = '', etapes = {} } = {}) {
  const d = points.depart || {};
  const a = points.arrivee || {};
  const coord = (v) => (Number.isFinite(nombre(v)) ? nombre(v) : null);
  return {
    leadId: String(lead.id),
    nom: infos.nom || lead.title || '',
    etape: etapes[lead.step_id] || String(lead.step || lead.step_id || ''),
    statut: String(lead.status || ''),
    derniereActivite: derniereActivite(lead) || '',
    volume: Number.isFinite(nombre(infos.volume)) ? nombre(infos.volume) : null,
    dateChargement: infos.dateChargement || '',
    // Fin de la plage de chargement (Notion « Date de chargement », fin) ; vide = un seul jour.
    dateFin: infos.dateFin && infos.dateFin !== infos.dateChargement ? infos.dateFin : '',
    depart: infos.depart || '',
    arrivee: infos.arrivee || '',
    latD: coord(d.lat),
    lonD: coord(d.lon),
    latA: coord(a.lat),
    lonA: coord(a.lon),
    qualiteD: d.qualite || '',
    qualiteA: a.qualite || '',
    depD: departementDe(infos.depart),
    depA: departementDe(infos.arrivee),
    notionUrl: infos.notionUrl || '',
    nocrmUrl: nocrmBase ? `${nocrmBase.replace(/\/+$/, '')}/leads/${lead.id}` : '',
    // Prix TTC de la fiche Notion (elle fait foi) ; le montant noCRM à défaut.
    montant: [infos.prixTTC, lead.amount].map(nombre).find(Number.isFinite) ?? null,
    sansFiche: infos.sansFiche ? 'oui' : '',
    dateLivraison: infos.dateLivraison || '',
    dateLivraisonFin: infos.dateLivraisonFin && infos.dateLivraisonFin !== infos.dateLivraison ? infos.dateLivraisonFin : '',
    // Route réelle allégée (Valhalla), en JSON : la page et les suggestions s'en servent de couloir.
    trajet: infos.trajet && infos.trajet.length > 1 ? JSON.stringify(infos.trajet) : '',
    // Lecture des notes par l'IA (moteur/notes.js), en JSON ; l'empreinte évite de relire des notes inchangées.
    analyse: infos.analyse ? JSON.stringify(infos.analyse) : '',
    notesEmpreinte: infos.notesEmpreinte || '',
  };
}

// Code postal → département (Corse : 2A / 2B ; outre-mer : trois chiffres).
function departementDe(adresse) {
  const cp = (String(adresse || '').match(/\b(\d{5})\b/) || [])[1];
  if (!cp) return '';
  if (cp.startsWith('20')) return Number(cp) < 20200 ? '2A' : '2B';
  if (cp.startsWith('97')) return cp.slice(0, 3);
  return cp.slice(0, 2);
}

// « 12 rue X, 33000 Bordeaux » → « Bordeaux » ; sans code postal, le dernier morceau.
function villeDe(adresse) {
  const texte = String(adresse || '').trim();
  const apres = texte.match(/\b\d{5}\s+([^,]+)/);
  if (apres) return apres[1].trim();
  const avant = texte.match(/([^,]+?)\s*\(?\d{5}\)?\s*$/);
  if (avant) return avant[1].trim();
  const morceaux = texte.split(',').map((m) => m.trim()).filter(Boolean);
  return morceaux[morceaux.length - 1] || '';
}

const pareil = (x, y) => (x === null || x === undefined || x === '' ? '' : String(x))
  === (y === null || y === undefined || y === '' ? '' : String(y));

// La table est un miroir des dossiers vivants : ce qui manque est créé, ce qui a changé est
// mis à jour, ce qui n'est plus vivant (perdu, inactif, sorti des colonnes) est supprimé.
// Une ligne inchangée n'est pas réécrite — un second import sans nouveauté n'écrit rien.
function synchroniserDemandes(existantes, actives) {
  const parLead = new Map(existantes.map((l) => [String(l.leadId), l]));
  const vus = new Set();
  const creer = [];
  const maj = [];
  for (const ligne of actives) {
    const cle = String(ligne.leadId);
    vus.add(cle);
    const avant = parLead.get(cle);
    if (!avant) creer.push(ligne);
    else if (CHAMPS_DEMANDE.some((c) => !pareil(avant[c], ligne[c]))) maj.push({ ...ligne, id: avant.id });
  }
  const supprimer = existantes.filter((l) => !vus.has(String(l.leadId)));
  return { creer, maj, supprimer };
}

const jourDe = (texte) => {
  const m = String(texte || '').match(/^(\d{4})-(\d{2})-(\d{2})/);
  return m ? Date.UTC(+m[1], +m[2] - 1, +m[3]) / JOUR_MS : null;
};

// Plage de chargement en jours [début, fin] ; deux plages qui se chevauchent sont à 0 jour.
function plageDe(d) {
  const debut = jourDe(d.dateChargement);
  if (debut === null) return null;
  const fin = jourDe(d.dateFin);
  return [debut, fin !== null && fin > debut ? fin : debut];
}

// Les demandes qui tiennent sur la route de `ref` : départ ET arrivée dans le couloir, dans le
// bon sens de marche, et à une date proche. Avec `retour`, on cherche aussi sur la route
// inverse — de quoi remplir le camion qui revient à vide.
function demandesCompatibles(ref, trajet, toutes, options = {}) {
  const o = { ...REGLAGES_DEMANDES, ...options };
  const route = trajet && trajet.length > 1 ? trajet : trajetDe(ref);
  if (route.length < 2) return [];
  const sens = [{ nom: 'aller', route }];
  if (o.retour) sens.push({ nom: 'retour', route: [...route].reverse() });
  const plageRef = plageDe(ref);
  const resultats = [];
  for (const c of toutes) {
    if (String(c.leadId) === String(ref.leadId)) continue;
    const d = pointDepart(c);
    const a = pointArrivee(c);
    if (!d || !a) continue;
    const plageC = plageDe(c);
    const ecartJours = plageRef && plageC ? Math.max(0, plageC[0] - plageRef[1], plageRef[0] - plageC[1]) : null;
    if (ecartJours !== null && ecartJours > o.fenetreJours) continue;
    for (const s of sens) {
      const pd = projeterSurTrajet(d, s.route);
      const pa = projeterSurTrajet(a, s.route);
      if (pd.ecartKm > o.couloirKm || pa.ecartKm > o.couloirKm) continue;
      if (pd.abscisseKm - pa.abscisseKm > o.toleranceSensKm) continue;
      resultats.push({
        demande: c,
        sens: s.nom,
        ecartDepartKm: arrondi(pd.ecartKm),
        ecartArriveeKm: arrondi(pa.ecartKm),
        detourKm: arrondi(pd.ecartKm + pa.ecartKm),
        abscisseDepartKm: pd.abscisseKm,
        abscisseArriveeKm: pa.abscisseKm,
        ecartJours,
        dateInconnue: !plageC,
      });
      break;
    }
  }
  return resultats.sort((x, y) => x.detourKm - y.detourKm
    || (x.ecartJours ?? Infinity) - (y.ecartJours ?? Infinity));
}

const arrondi = (x) => Math.round(x * 10) / 10;

const MOIS_FR = { janvier: 1, janv: 1, fevrier: 2, fevr: 2, fev: 2, mars: 3, avril: 4, avr: 4, mai: 5, juin: 6, juillet: 7, juil: 7,
  aout: 8, septembre: 9, sept: 9, sep: 9, octobre: 10, oct: 10, novembre: 11, nov: 11, decembre: 12, dec: 12 };

// « Date / heure d'intervention » de la fiche Notion — c'est la date de LIVRAISON qui fait foi.
// Texte libre : « 12/10/2026 matin », « du 12 au 14 octobre », « 12-13/10 », « lundi 12 octobre ».
// Rend { debut, fin } en AAAA-MM-JJ, ou null. Sans année, on prend celle de `reference`, ou la
// suivante si la date tomberait plus de deux mois avant elle.
function lireDatesIntervention(texte, reference = '') {
  const nu = String(texte || '').toLowerCase().normalize('NFD').replace(/\p{Mn}/gu, '');
  const trouvees = [];
  const ref = /^\d{4}-\d{2}-\d{2}/.test(reference) ? reference : new Date().toISOString().slice(0, 10);
  const anneeRef = Number(ref.slice(0, 4));
  const iso = (j, m, a) => {
    if (!(j >= 1 && j <= 31 && m >= 1 && m <= 12)) return null;
    let annee = a ? (a < 100 ? 2000 + a : a) : anneeRef;
    let d = `${annee}-${String(m).padStart(2, '0')}-${String(j).padStart(2, '0')}`;
    if (!a && jourDe(d) < jourDe(ref) - 60) {
      annee += 1;
      d = `${annee}-${String(m).padStart(2, '0')}-${String(j).padStart(2, '0')}`;
    }
    return d;
  };
  // 12/10/2026, 12/10, et « 12-13/10 » (deux jours, un mois)
  for (const m of nu.matchAll(/\b(\d{1,2})(?:\s*[-–]\s*(\d{1,2}))?\s*[/.]\s*(\d{1,2})(?:\s*[/.]\s*(\d{2,4}))?\b/g)) {
    const a = m[4] ? Number(m[4]) : null;
    trouvees.push(iso(Number(m[1]), Number(m[3]), a));
    if (m[2]) trouvees.push(iso(Number(m[2]), Number(m[3]), a));
  }
  // « 12 octobre 2026 », « du 12 au 14 octobre »
  for (const m of nu.matchAll(/\b(\d{1,2})(?:er)?(?:\s*(?:au|-|–|et)\s*(\d{1,2})(?:er)?)?\s+([a-z]+)\.?(?:\s+(\d{4}))?/g)) {
    const mois = MOIS_FR[m[3]];
    if (!mois) continue;
    const a = m[4] ? Number(m[4]) : null;
    trouvees.push(iso(Number(m[1]), mois, a));
    if (m[2]) trouvees.push(iso(Number(m[2]), mois, a));
  }
  // Périodes approximatives, fréquentes sur un devis : « fin octobre 2026 », « mi-octobre », « début décembre ».
  // début = du 1er au 10, mi = du 10 au 20, fin = du 20 au dernier jour.
  if (!trouvees.length) {
    for (const m of nu.matchAll(/\b(debut|mi|fin)[\s-]+([a-z]+)\.?(?:\s+(\d{4}))?/g)) {
      const mois = MOIS_FR[m[2]];
      if (!mois) continue;
      const a = m[3] ? Number(m[3]) : null;
      const dernier = new Date(Date.UTC(2001, mois, 0)).getUTCDate();
      const [j1, j2] = { debut: [1, 10], mi: [10, 20], fin: [20, dernier] }[m[1]];
