// Les notes d'un dossier, en un seul texte borné, sources étiquetées.
function texteNotes({ corpsNotion = '', descriptionNocrm = '', commentairesNocrm = [] } = {}) {
  const morceaux = [];
  if (String(corpsNotion).trim()) morceaux.push(`[Fiche Notion]\n${String(corpsNotion).trim()}`);
  if (String(descriptionNocrm).trim()) morceaux.push(`[Description noCRM]\n${String(descriptionNocrm).trim()}`);
  const commentaires = (commentairesNocrm || [])
    .map((c) => `${String(c.created_at || '').slice(0, 10)} — ${String(c.content || c.text || '').trim()}`)
    .filter((c) => !/—\s*$/.test(c));
  if (commentaires.length) morceaux.push(`[Commentaires noCRM]\n${commentaires.join('\n')}`);
  const texte = morceaux.join('\n\n');
  return texte.length > LONGUEUR_NOTES_MAX ? `${texte.slice(0, LONGUEUR_NOTES_MAX)}\n[…]` : texte;
