// Ce que rend l'IA, revérifié : champs connus, textes bornés. Tout écart → pas d'analyse (le
// dossier reste utilisable, la note de groupage l'ignore simplement).
const plat = (t) => String(t || '').toLowerCase().normalize('NFD').replace(/\p{Mn}/gu, '').replace(/[^a-z0-9]+/g, ' ').trim();

// Un repère n'est gardé que si sa preuve se retrouve dans les notes : ce que l'IA ne peut pas
// citer, elle l'a inventé. Sans texte fourni, pas de contrôle (anciennes lectures, tests).
function reperesProuves(reperes, texte = null) {
  const notes = texte === null ? null : ` ${plat(texte)} `;
  const gardes = [];
  for (const r of Array.isArray(reperes) ? reperes : []) {
    const nom = typeof r === 'string' ? r : r && r.repere;
    if (!(nom in REPERES) || gardes.includes(nom)) continue;
    if (notes !== null) {
      const preuve = plat(r && r.preuve);
      if (preuve.length < 3 || !notes.includes(` ${preuve} `)) continue;
    }
    gardes.push(nom);
  }
  return gardes;
}

function analyseVerifiee(reponseApi) {
