    if (!a || typeof a !== 'object') return null;
    return {
      resume: borne(a.resume, 400),
      flexibiliteDates: FLEXIBILITES.includes(a.flexibiliteDates) ? a.flexibiliteDates : 'inconnue',
      precisionDates: borne(a.precisionDates, 200),
      reperes: reperesProuves(a.reperes),
      contraintes: (Array.isArray(a.contraintes) ? a.contraintes : []).map((c) => borne(c, 120)).filter(Boolean).slice(0, 5),
    };
  } catch {
    return null;
  }
}

