  const dateDebut = debuts[0] || fins[0] || '';
  const jj = (iso) => (iso ? `${iso.slice(8, 10)}/${iso.slice(5, 7)}` : '');
  return {
    nom: `${villeDe(tete.depart) || '?'} → ${villeDe(tete.arrivee) || '?'}${dateDebut ? ` — ${jj(dateDebut)}` : ''}`,
