function avisVerifie(reponseApi, leadIds = []) {
  try {
    if (!reponseApi || reponseApi.error) return null;
    const brut = reponseApi.choices?.[0]?.message?.content;
    const a = typeof brut === 'string' ? JSON.parse(brut) : brut;
    if (!a || typeof a !== 'object' || !a.avis) return null;
    const connus = new Set(leadIds.map(String));
    return {
      avis: borne(a.avis, 700),
      priorites: (Array.isArray(a.priorites) ? a.priorites : []).map(String).filter((id) => connus.has(id)),
      risques: (Array.isArray(a.risques) ? a.risques : []).map((r) => borne(r, 160)).filter(Boolean).slice(0, 4),
    };
  } catch {
    return null;
  }
}


const { leadIds } = $('Groupage à juger').first().json;
const a = avisVerifie($input.first().json, leadIds);
return [{ json: a || { erreur: 'L’IA n’a pas pu répondre.' } }];
